// NEXAI Voice · Verfügbarkeit — toolCallId lesen (flach ODER Vapi-Envelope), 14-Tage-Fenster
const TZ='Europe/Berlin';
const root=$input.first().json||{};
const body=(root.body && typeof root.body==='object')?root.body:root;
let toolCallId='';
if(body && body.message && Array.isArray(body.message.toolCalls) && body.message.toolCalls[0]) toolCallId=body.message.toolCalls[0].id||'';
else toolCallId=body.toolCallId||'';
const now=$now.setZone(TZ);
return [{ json: { toolCallId, windowMinISO: now.toISO(), windowMaxISO: now.plus({days:14}).toISO() } }];

// NEXAI Voice · Verfügbarkeit — freie Slots über den Tag gestreut (Vormittag/Mittag/Nachmittag)
const TZ = 'Europe/Berlin';
const DAY_START = 8, DAY_END = 17, SLOT_MIN = 30, LEAD_MIN = 120, HORIZON = 14, MAX_DAYS = 3;
const WINDOWS = [[8, 12], [12, 15], [15, 17]]; // Vormittag / Mittag / Nachmittag
const WD = ['', 'Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag', 'Sonntag'];
const ov = (aS, aE, bS, bE) => aS < bE && bS < aE;
function busyFromEvents(items) {
  const busy = [];
  for (const it of items) {
    const e = (it && it.json) ? it.json : it;
    if (!e) continue;
    if (e.status === 'cancelled') continue;
    if (e.transparency === 'transparent') continue;
    const s = e.start && (e.start.dateTime || e.start.date);
    const en = e.end && (e.end.dateTime || e.end.date);
    if (!s || !en) continue;
    const es = DateTime.fromISO(s).setZone(TZ), ee = DateTime.fromISO(en).setZone(TZ);
    if (!es.isValid || !ee.isValid) continue;
    busy.push([es, ee]);
  }
  return busy;
}
// Ersten freien 30-Min-Slot in einem Tages-Fenster [winFrom..winTo) finden
function firstFreeInWindow(busy, day, winFrom, winTo, earliest, limit) {
  const winEnd = day.set({ hour: winTo, minute: 0, second: 0, millisecond: 0 });
  let cur = day.set({ hour: winFrom, minute: 0, second: 0, millisecond: 0 });
  if (cur < earliest) {
    cur = earliest.set({ second: 0, millisecond: 0 });
    if (cur.minute !== 0 && cur.minute !== 30) cur = cur.minute < 30 ? cur.set({ minute: 30 }) : cur.plus({ hours: 1 }).set({ minute: 0 });
  }
  while (cur < winEnd && cur < limit) {
    const h = cur.hour + cur.minute / 60;
    if (h >= DAY_START && h + SLOT_MIN / 60 <= DAY_END && cur >= earliest) {
      const cE = cur.plus({ minutes: SLOT_MIN });
      if (!busy.some(([bs, be]) => ov(cur, cE, bs, be))) return cur;
    }
    cur = cur.plus({ minutes: SLOT_MIN });
  }
  return null;
}
// Pro Werktag je einen freien Slot aus jedem Fenster (gestreut über den Tag)
function collectSpread(busy, now, maxDays, windows) {
  const earliest = now.plus({ minutes: LEAD_MIN }), limit = now.plus({ days: HORIZON });
  const out = [];
  let day = now.startOf('day'), daysUsed = 0, guard = 0;
  while (daysUsed < maxDays && day < limit && guard < 60) {
    guard++;
    if (day.weekday >= 1 && day.weekday <= 5) {
      let added = 0;
      for (const [wf, wt] of windows) {
        const s = firstFreeInWindow(busy, day, wf, wt, earliest, limit);
        if (s) { out.push(s); added++; }
      }
      if (added > 0) daysUsed++;
    }
    day = day.plus({ days: 1 });
  }
  return out;
}
const lbl = dt => WD[dt.weekday] + ' ' + dt.toFormat('dd.LL.') + ' um ' + dt.toFormat('HH:mm');
const now = $now.setZone(TZ);
const busy = busyFromEvents($input.all());
const slots = collectSpread(busy, now, MAX_DAYS, WINDOWS);
const toolCallId = $('Parse').first().json.toolCallId;
const heute = 'Heute ist ' + WD[now.weekday] + ', der ' + now.toFormat('dd.LL.yyyy') + '.';
let result;
if (slots.length === 0) {
  result = heute + ' In den nächsten 14 Tagen ist leider kein Termin frei. Entschuldige dich und biete an, dass sich das Team beim Anrufer meldet.';
} else {
  result = heute + ' Freie Zeiten (Europe/Berlin, 30 Min — eine Auswahl über den Tag, NICHT alle freien Zeiten): ' + slots.map(lbl).join(' | ') + '. Schlage dem Anrufer 2 bis 3 passend zu seinem Wunsch vor. Möchte er SPÄTER oder eine andere Uhrzeit: nenne die späteren Zeiten aus dieser Liste (z. B. um 15 Uhr) ODER rufe direkt book_appointment mit seiner konkreten Wunschuhrzeit auf — der Kalender ist werktags von 8 bis 17 Uhr offen, sage also NIEMALS, es gebe nichts Späteres. Erfinde keine Zeiten; konkrete Wünsche immer über book_appointment prüfen und buchen.';
}
return [{ json: { results: [{ toolCallId, result }] } }];
